const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程' },
      { kind: 'text', payload: '6x+5=2x+11' },
      { kind: 'text', payload: '1. 移项' },
      { kind: 'text', payload: '6x-2x=11-5' },
      { kind: 'text', payload: '2. 合并同类项' },
      { kind: 'text', payload: '4x=6' },
      { kind: 'text', payload: '3. 系数化为 1' },
      { kind: 'text', payload: 'x=6/4=3/2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = Math.max(12, Math.round(W * 0.06));
    var cardW = W - 2 * margin;
    var ink = '#1F2A44';
    var accent = '#2F6FED';
    var border = '#C9D6EE';
    var light = '#F4F7FE';
    var white = '#FFFFFF';
    var paths = [];
    var pathNodes = [];
    var labelNodes = [];
    var pathCounter = 0;

    function addRect(x, y, w, h, fill) {
      var id = 'p' + (pathCounter++);
      var cmds = [['M', x, y], ['L', x + w, y], ['L', x + w, y + h], ['L', x, y + h], ['Z']];
      paths.push({ id: id, commands: cmds });
      pathNodes.push({ type: 'path', pathId: id, fill: fill });
    }

    function addArrow(x1, y1, x2, y2, fill) {
      var id = 'p' + (pathCounter++);
      var cmds = visualSdk.arrow(x1, y1, x2, y2, {});
      paths.push({ id: id, commands: cmds });
      pathNodes.push({ type: 'path', pathId: id, fill: fill, stroke: { width: 2 } });
    }

    function addLabel(index, x, y, hAlign, vAlign, color) {
      labelNodes.push({
        type: 'label',
        contentId: metrics[index].contentId,
        anchor: { x: x, y: y },
        hAlign: hAlign,
        vAlign: vAlign,
        color: color
      });
    }

    addRect(0, 0, W, H, white);
    addLabel(0, W / 2, H * 0.07, 'center', 'middle', ink);

    var origY = H * 0.14;
    var origH = H * 0.11;
    var inset = Math.max(1, Math.round(W * 0.003));
    addRect(margin, origY, cardW, origH, accent);
    addRect(margin + inset, origY + inset, cardW - 2 * inset, origH - 2 * inset, light);
    addLabel(1, W / 2, origY + origH / 2, 'center', 'middle', ink);

    var stepTop = H * 0.30;
    var stepBottom = H * 0.94;
    var gap = H * 0.07;
    var boxH = (stepBottom - stepTop - 2 * gap) / 3;
    var boxX = margin;
    var boxW = cardW;

    for (var i = 0; i < 3; i++) {
      var boxY = stepTop + i * (boxH + gap);
      addRect(boxX, boxY, boxW, boxH, border);
      addRect(boxX + inset, boxY + inset, boxW - 2 * inset, boxH - 2 * inset, white);
      addLabel(2 + i * 2, W / 2, boxY + boxH * 0.32, 'center', 'middle', accent);
      addLabel(3 + i * 2, W / 2, boxY + boxH * 0.68, 'center', 'middle', ink);
    }

    for (var j = 0; j < 2; j++) {
      var y1 = stepTop + j * (boxH + gap) + boxH + gap * 0.15;
      var y2 = stepTop + (j + 1) * (boxH + gap) - gap * 0.15;
      addArrow(W / 2, y1, W / 2, y2, accent);
    }

    return {
      schemaVersion: 1,
      sceneId: 'solve-linear-flow',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: pathNodes.concat(labelNodes)
      }
    };
  }
};
